19	// maxTranscriptFileBytes bounds how much of a transcript file is read into
20	// memory. Claude session files grow forward, so for a larger file only the
21	// tail (most recent conversation) is read.
22	const maxTranscriptFileBytes = 32 * 1024 * 1024
