201	// jsonlLine is the top-level structure of each JSONL event line.
202	type jsonlLine struct {
203		Type    string `json:"type"`
204		Message struct {
205			Role    string          `json:"role"`
206			Content json.RawMessage `json:"content"`
207		} `json:"message"`
208	}
