228	// renderJSONL parses raw JSONL data and returns the rendered transcript.
229	// Only the last maxMessages user/assistant messages are included, and the
230	// result is byte-capped to the most recent maxRenderBytes.
231	func renderJSONL(data []byte, maxMessages int) string {
232		type msg struct {
233			isUser bool
234			text   string
235		}
236	
237		var messages []msg
238		for _, rawLine := range strings.Split(string(data), "\n") {
239			rawLine = strings.TrimSpace(rawLine)
240			if rawLine == "" {
241				continue
242			}
243			var line jsonlLine
244			if err := json.Unmarshal([]byte(rawLine), &line); err != nil {
245				continue
246			}
247			if line.Type != "user" && line.Type != "assistant" {
248				continue
249			}
250			text := extractContent(line.Message.Content)
251			if strings.TrimSpace(text) == "" {
252				continue
253			}
254			// Header comes from the validated line.Type, not message.role, which
255			// can be absent/unexpected on some events.
256			messages = append(messages, msg{isUser: line.Type == "user", text: text})
257		}
258	
259		// Keep only the last maxMessages.
260		if maxMessages > 0 && len(messages) > maxMessages {
261			messages = messages[len(messages)-maxMessages:]
262		}
263	
264		var sb strings.Builder
265		for i, m := range messages {
266			header := "⏺ Claude"
267			if m.isUser {
268				header = "› You"
269			}
270			if i > 0 {
271				sb.WriteByte('\n')
272			}
273			sb.WriteString(header)
274			sb.WriteByte('\n')
275			sb.WriteString(m.text)
276			sb.WriteByte('\n')
277		}
278		return capTail(sb.String())
279	}
