281	// extractContent converts a raw JSON content field (string or block array)
282	// into plain text.
283	func extractContent(raw json.RawMessage) string {
284		if len(raw) == 0 {
285			return ""
286		}
287	
288		// Try string first.
289		var s string
290		if err := json.Unmarshal(raw, &s); err == nil {
291			return s
292		}
293	
294		// Try array of blocks.
295		var blocks []map[string]any
296		if err := json.Unmarshal(raw, &blocks); err != nil {
297			return ""
298		}
299	
300		var parts []string
301		for _, block := range blocks {
302			blockType, _ := block["type"].(string)
303			switch blockType {
304			case "text":
305				if t, _ := block["text"].(string); t != "" {
306					parts = append(parts, t)
307				}
308			case "tool_use":
309				if name, _ := block["name"].(string); name != "" {
310					parts = append(parts, "⚙ "+name)
311				}
312			// thinking, tool_result, and anything else: skip
313			}
314		}
315		return strings.Join(parts, "\n")
316	}
