17	// LoadOrCreateToken reads the pairing token from disk, generating one if absent.
18	func LoadOrCreateToken(configDir string) (string, error) {
19		path := filepath.Join(configDir, tokenFile)
20	
21		data, err := os.ReadFile(path)
22		if err == nil {
23			if t := strings.TrimSpace(string(data)); t != "" {
24				return t, nil
25			}
26		}
27	
28		// Generate 256-bit token
29		raw := make([]byte, 32)
30		if _, err := rand.Read(raw); err != nil {
31			return "", fmt.Errorf("generate token: %w", err)
32		}
33		token := base64.RawURLEncoding.EncodeToString(raw)
34	
35		if err := os.MkdirAll(configDir, 0o700); err != nil {
36			return "", fmt.Errorf("create config dir: %w", err)
37		}
38		if err := os.WriteFile(path, []byte(token+"\n"), 0o600); err != nil {
39			return "", fmt.Errorf("write token: %w", err)
40		}
41		return token, nil
42	}
