73	// primaryLANIP returns the best non-loopback IPv4 address of this machine.
74	func primaryLANIP() string {
75		ifaces, err := net.Interfaces()
76		if err != nil {
77			return "127.0.0.1"
78		}
79		for _, iface := range ifaces {
80			if iface.Flags&net.FlagUp == 0 || iface.Flags&net.FlagLoopback != 0 {
81				continue
82			}
83			addrs, err := iface.Addrs()
84			if err != nil {
85				continue
86			}
87			for _, addr := range addrs {
88				var ip net.IP
89				switch v := addr.(type) {
90				case *net.IPNet:
91					ip = v.IP
92				case *net.IPAddr:
93					ip = v.IP
94				}
95				if ip == nil || ip.IsLoopback() {
96					continue
97				}
98				if ip4 := ip.To4(); ip4 != nil {
99					return ip4.String()
100				}
101			}
102		}
103		return "127.0.0.1"
104	}
